// sw.js — offline support (spec §6: offline-first). Generated by
// scripts/build.mjs, which fills in the version and the file list.
//
// Strategy: cache-first for the app's own files. Everything the app needs is
// precached at install, so after the first visit it starts without network.
// A new deploy has a new VERSION → a new cache; the old one is deleted once
// the new worker takes over (on the next launch, never mid-session).

const VERSION = '__VERSION__';
const ASSETS = __ASSETS__;
const CACHE = `codeeditor-${VERSION}`;

self.addEventListener('install', (event) => {
  event.waitUntil(caches.open(CACHE).then((cache) => cache.addAll(ASSETS)));
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    for (const key of await caches.keys()) {
      if (key.startsWith('codeeditor-') && key !== CACHE) await caches.delete(key);
    }
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  // Always from the network: it's how the app learns that a newer build exists.
  if (url.pathname.endsWith('/version.json')) return;
  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    const hit = await cache.match(req, { ignoreSearch: true });
    if (hit) return hit;
    try {
      return await fetch(req);
    } catch (err) {
      if (req.mode === 'navigate') return (await cache.match('./')) || (await cache.match('index.html'));
      throw err;
    }
  })());
});

self.addEventListener('message', (event) => {
  if (event.data === 'skip-waiting') self.skipWaiting();
});
